1	//! Export the resolved `jj-lib` version as `JJ_LIB_VERSION`,
2	//! guard the single-name convention, and generate the config
3	//! schema from the `vc-config.toml` prototype.
4	//!
5	//! jj-lib exports no version constant of its own, so the only
6	//! statement of what this binary links against is the resolved
7	//! version in `Cargo.lock`:
8	//!
9	//! - the lock is read from `$CARGO_MANIFEST_DIR` directly, not by
10	//!   walking ancestors: we are not a workspace, and a walk can
11	//!   bind a sibling project's lock, which is worse than failing.
12	//! - a missing or jj-lib-less lock fails the build rather than
13	//!   emitting an "unknown" that would later be reported as fact.
14	//!
15	//! The name guard (chores-16, 0.78.3): a suffixed version marks a
16	//! dev rung, and a dev rung must never carry the stable package
17	//! name, or installing it replaces the stable `vc-x1` binary with
18	//! unpushed code. It lives here rather than in a `#[test]` because
19	//! `cargo install` never runs tests: a build script runs on every
20	//! cargo verb, so the forbidden combination fails to compile at
21	//! all, install included.
22	
23	use std::path::Path;
24	
25	/// Extract `jj-lib`'s resolved version from `Cargo.lock` text.
26	///
27	/// Scans for the `[[package]]` block whose `name` is `jj-lib` and
28	/// returns that block's `version`. Line-based rather than a TOML
29	/// parse: build scripts get no dev-dependencies, and the lock's
30	/// shape is fixed by cargo.
31	fn jj_lib_version(lock: &str) -> Option<String> {
32	    let mut in_jj_lib = false;
33	    for line in lock.lines() {
34	        let line = line.trim();
35	        if line == "[[package]]" {
36	            in_jj_lib = false;
37	        } else if let Some(rest) = line.strip_prefix("name = ") {
38	            in_jj_lib = rest.trim_matches('"') == "jj-lib";
39	        } else if let Some(rest) = line.strip_prefix("version = ")
40	            && in_jj_lib
41	        {
42	            return Some(rest.trim_matches('"').to_string());
43	        }
44	    }
45	    None
46	}
47	
48	/// The single-name convention's guard: refuse to build a suffixed
49	/// (dev-rung) version under the stable package name.
50	///
51	/// Reported via the `cargo::error` directive rather than `panic!`:
52	/// cargo then prints one clean error line and fails the build,
53	/// instead of wrapping a build-script panic in exit-status and
54	/// backtrace noise.
55	fn guard_single_name() {
56	    let name = env!("CARGO_PKG_NAME");
57	    let version = env!("CARGO_PKG_VERSION");
58	    if version.contains('-') && name == "vc-x1" {
59	        // The version is not echoed in the text: cargo's own
60	        // `error: <name>@<version>:` prefix already carries it.
61	        println!("cargo::error=");
62	        println!("cargo::error=A suffixed version is used with the stable package name, `vc-x1`");
63	        println!("cargo::error=so refusing to build `vc-x1` as it is the stable binary name.");
64	        println!("cargo::error=");
65	    }
66	}
67	
68	/// One key parsed from the `vc-config.toml` prototype, metadata
69	/// as raw strings (typing happens at render time in
70	/// `render_config_schema`).
71	struct ProtoKey {
72	    path: String,
73	    homes: Vec<String>,
74	    kind: String,
75	    doc: String,
76	    used_by: String,
77	    /// Override url; the norm is `None`, deriving
78	    /// `<reference-base>vc-config.md#<anchor_slug(path)>`.
79	    reference: Option<String>,
80	    default: Option<String>,
81	    example: Option<String>,
82	    required: bool,
83	}
84	
85	/// Parse a TOML basic-string body (the text between the quotes),
86	/// unescaping `\"` and `\\`. Anything fancier (unicode escapes,
87	/// multi-line strings) is out of the prototype's dialect and
88	/// fails the build via the caller's validation.
89	fn unescape_basic_string(body: &str) -> String {
90	    let mut out = String::with_capacity(body.len());
91	    let mut chars = body.chars();
92	    while let Some(c) = chars.next() {
93	        if c == '\\' {
94	            match chars.next() {
95	                Some('"') => out.push('"'),
96	                Some('\\') => out.push('\\'),
97	                other => panic!("vc-config.toml: unsupported escape \\{other:?}"),
98	            }
99	        } else {
100	            out.push(c);
101	        }
102	    }
103	    out
104	}
105	
106	/// Parse one metadata value: a quoted string, a `[...]` string
107	/// array (returned joined by `\u{0}` for the caller to split), a
108	/// bare integer, or a bare bool. Returns the raw string form.
109	fn parse_value(raw: &str) -> String {
110	    let raw = raw.trim();
111	    if let Some(body) = raw.strip_prefix('"') {
112	        let Some(body) = body.strip_suffix('"') else {
113	            panic!("vc-config.toml: unterminated string: {raw}");
114	        };
115	        unescape_basic_string(body)
116	    } else {
117	        raw.to_string()
118	    }
119	}
120	
121	/// Line-based parse of the `vc-config.toml` prototype into
122	/// `ProtoKey`s, file order preserved.
123	///
124	/// Line-based for the same reason `jj_lib_version` is: build
125	/// scripts see no dev-dependencies, and the prototype's dialect
126	/// is ours to bound (single-line `key = value` entries, dotted
127	/// table headers with optionally-quoted segments, `#` comments).
128	fn parse_prototype(text: &str) -> (String, Vec<ProtoKey>) {
129	    let mut keys: Vec<ProtoKey> = Vec::new();
130	    let mut base: Option<String> = None;
131	    let mut current: Option<(String, Vec<(String, String)>)> = None;
132	
133	    fn finish(
134	        keys: &mut Vec<ProtoKey>,
135	        base: &mut Option<String>,
136	        current: Option<(String, Vec<(String, String)>)>,
137	    ) {
138	        let Some((path, fields)) = current else {
139	            return;
140	        };
141	        if path == "vc-config" {
142	            for (name, value) in fields {
143	                match name.as_str() {
144	                    "reference-base" => *base = Some(value),
145	                    other => panic!("vc-config.toml: [vc-config]: unknown entry {other:?}"),
146	                }
147	            }
148	            return;
149	        }
150	        let mut homes: Vec<String> = Vec::new();
151	        let mut kind = None;
152	        let mut doc = None;
153	        let mut used_by = None;
154	        let mut reference = None;
155	        let mut default = None;
156	        let mut example = None;
157	        let mut required = false;
158	        for (name, value) in fields {
159	            match name.as_str() {
160	                "homes" => {
161	                    homes = value.split('\u{0}').map(str::to_string).collect();
162	                }
163	                "kind" => kind = Some(value),
164	                "doc" => doc = Some(value),
165	                "used-by" => used_by = Some(value),
166	                "reference" => reference = Some(value),
167	                "default" => default = Some(value),
168	                "example" => example = Some(value),
169	                "required" => match value.as_str() {
170	                    "true" => required = true,
171	                    "false" => required = false,
172	                    other => panic!("vc-config.toml: [{path}] required = {other}: not a bool"),
173	                },
174	                other => panic!("vc-config.toml: [{path}]: unknown entry {other:?}"),
175	            }
176	        }
177	        let missing = |what: &str| -> ! { panic!("vc-config.toml: [{path}] is missing {what}") };
178	        let kind = kind.unwrap_or_else(|| missing("kind"));
179	        if !matches!(kind.as_str(), "str" | "usize" | "item-list") {
180	            panic!("vc-config.toml: [{path}] kind = {kind:?}: not str/usize/item-list");
181	        }
182	        if kind == "usize"
183	            && let Some(d) = &default
184	            && d.parse::<usize>().is_err()
185	        {
186	            panic!("vc-config.toml: [{path}] default {d:?} is not a usize");
187	        }
188	        if homes.is_empty() {
189	            missing("homes");
190	        }
191	        if default.is_none() && example.is_none() {
192	            missing("a default or an example");
193	        }
194	        let doc = doc.unwrap_or_else(|| missing("doc"));
195	        let used_by = used_by.unwrap_or_else(|| missing("used-by"));
196	        keys.push(ProtoKey {
197	            path,
198	            homes,
199	            kind,
200	            doc,
201	            used_by,
202	            reference,
203	            default,
204	            example,
205	            required,
206	        });
207	    }
208	
209	    for line in text.lines() {
210	        let trimmed = line.trim();
211	        if trimmed.is_empty() || trimmed.starts_with('#') {
212	            continue;
213	        }
214	        if let Some(inner) = trimmed.strip_prefix('[').and_then(|s| s.strip_suffix(']')) {
215	            finish(&mut keys, &mut base, current.take());
216	            current = Some((inner.replace('"', ""), Vec::new()));
217	            continue;
218	        }
219	        let Some((name, value)) = trimmed.split_once('=') else {
220	            panic!("vc-config.toml: unparseable line: {trimmed}");
221	        };
222	        let Some((_, fields)) = current.as_mut() else {
223	            panic!("vc-config.toml: entry before first table header: {trimmed}");
224	        };
225	        let name = name.trim().to_string();
226	        let raw = value.trim();
227	        let value = if name == "homes" {
228	            let Some(body) = raw.strip_prefix('[').and_then(|s| s.strip_suffix(']')) else {
229	                panic!("vc-config.toml: homes must be an array: {raw}");
230	            };
231	            body.split(',')
232	                .map(|s| parse_value(s.trim()))
233	                .collect::<Vec<_>>()
234	                .join("\u{0}")
235	        } else {
236	            parse_value(raw)
237	        };
238	        fields.push((name, value));
239	    }
240	    finish(&mut keys, &mut base, current);
241	
242	    let mut paths: Vec<&str> = keys.iter().map(|k| k.path.as_str()).collect();
243	    paths.sort_unstable();
244	    paths.dedup();
245	    if paths.len() != keys.len() {
246	        panic!("vc-config.toml: duplicate key path(s)");
247	    }
248	    let Some(base) = base else {
249	        panic!("vc-config.toml: no [vc-config] reference-base");
250	    };
251	    (base, keys)
252	}
253	
254	/// A key path's GitHub-style heading anchor: lowercased, keeping
255	/// only `[a-z0-9-]` (dots and `<`/`>` drop out), spaces to
256	/// hyphens. `bot-session.col-width` -> `bot-sessioncol-width`,
257	/// matching the slug of that key's `##` heading in vc-config.md.
258	fn anchor_slug(path: &str) -> String {
259	    path.chars()
260	        .filter_map(|c| match c {
261	            'a'..='z' | '0'..='9' | '-' => Some(c),
262	            'A'..='Z' => Some(c.to_ascii_lowercase()),
263	            ' ' => Some('-'),
264	            _ => None,
265	        })
266	        .collect()
267	}
268	
269	/// Render the generated schema module: the `SCHEMA_GEN` table
270	/// plus one `<PATH>_DEFAULT` constant per non-dynamic defaulted
271	/// key, typed by `kind`. Each key's reference is its override
272	/// url when given, else derived from `base` + the key's
273	/// vc-config.md anchor.
274	fn render_config_schema(keys: &[ProtoKey], base: &str) -> String {
275	    let mut out = String::from(
276	        "// Generated from vc-config.toml by build.rs. Do not edit.\n\
277	         static SCHEMA_GEN: &[ConfigKey] = &[\n",
278	    );
279	    for key in keys {
280	        let homes = key
281	            .homes
282	            .iter()
283	            .map(|h| match h.as_str() {
284	                "user" => "Home::User",
285	                "workspace-code" => "Home::WorkspaceCode",
286	                "workspace-bot" => "Home::WorkspaceBot",
287	                other => panic!("vc-config.toml: [{}] unknown home {other:?}", key.path),
288	            })
289	            .collect::<Vec<_>>()
290	            .join(", ");
291	        let kind = match key.kind.as_str() {
292	            "str" => "ValueKind::Str",
293	            "usize" => "ValueKind::Usize",
294	            "item-list" => "ValueKind::ItemList",
295	            other => panic!("vc-config.toml: [{}] unknown kind {other:?}", key.path),
296	        };
297	        let opt = |v: &Option<String>| match v {
298	            Some(s) => format!("Some({s:?})"),
299	            None => "None".to_string(),
300	        };
301	        // `blob/HEAD` resolves to the repo's default branch at
302	        // click time, so the base names only the repo and no
303	        // branch is baked in (a build-time branch would point
304	        // shipped references at whatever the builder had checked
305	        // out). The join is GitHub-shaped; a host needing another
306	        // shape uses the per-key `reference` override.
307	        let reference = key.reference.clone().unwrap_or_else(|| {
308	            format!(
309	                "{}/blob/HEAD/vc-config.md#{}",
310	                base.trim_end_matches('/'),
311	                anchor_slug(&key.path)
312	            )
313	        });
314	        out.push_str(&format!(
315	            "    ConfigKey {{\n\
316	             \x20       path: {path:?},\n\
317	             \x20       homes: &[{homes}],\n\
318	             \x20       kind: {kind},\n\
319	             \x20       default: {default},\n\
320	             \x20       required: {required},\n\
321	             \x20       dynamic: {dynamic},\n\
322	             \x20       doc: {doc:?},\n\
323	             \x20       used_by: {used_by:?},\n\
324	             \x20       example: {example},\n\
325	             \x20       reference: {reference:?},\n\
326	             \x20   }},\n",
327	            path = key.path,
328	            default = opt(&key.default),
329	            required = key.required,
330	            dynamic = key.path.contains('<'),
331	            doc = key.doc,
332	            used_by = key.used_by,
333	            example = opt(&key.example),
334	            reference = reference,
335	        ));
336	    }
337	    out.push_str("];\n");
338	
339	    for key in keys {
340	        let Some(default) = &key.default else {
341	            continue;
342	        };
343	        if key.path.contains('<') {
344	            continue;
345	        }
346	        let name = format!(
347	            "{}_DEFAULT",
348	            key.path.to_uppercase().replace(['.', '-'], "_")
349	        );
350	        // Not every generated constant has a non-test consumer
351	        // (e.g. the items default's runtime twin is
352	        // `ItemSet::BUILTIN`), so silence dead_code per constant.
353	        out.push_str("#[allow(dead_code)]\n");
354	        match key.kind.as_str() {
355	            "usize" => out.push_str(&format!("pub const {name}: usize = {default};\n")),
356	            _ => out.push_str(&format!("pub const {name}: &str = {default:?};\n")),
357	        }
358	    }
359	    out
360	}
361	
362	/// Parse the prototype and write the generated schema module
363	/// into `$OUT_DIR/config_schema_gen.rs`.
364	fn generate_config_schema(manifest_dir: &str) {
365	    let proto_path = Path::new(manifest_dir).join("vc-config.toml");
366	    println!("cargo::rerun-if-changed={}", proto_path.display());
367	    let text = match std::fs::read_to_string(&proto_path) {
368	        Ok(text) => text,
369	        Err(e) => panic!("cannot read {}: {e}", proto_path.display()),
370	    };
371	    let (base, keys) = parse_prototype(&text);
372	    let out_dir = match std::env::var("OUT_DIR") {
373	        Ok(dir) => dir,
374	        Err(e) => panic!("OUT_DIR unset: {e}"),
375	    };
376	    let gen_path = Path::new(&out_dir).join("config_schema_gen.rs");
377	    if let Err(e) = std::fs::write(&gen_path, render_config_schema(&keys, &base)) {
378	        panic!("cannot write {}: {e}", gen_path.display());
379	    }
380	}
381	
382	/// Read the lock beside `Cargo.toml` and emit the version env var;
383	/// enforce the single-name guard first, then generate the config
384	/// schema from the prototype.
385	fn main() {
386	    guard_single_name();
387	
388	    let manifest_dir = match std::env::var("CARGO_MANIFEST_DIR") {
389	        Ok(dir) => dir,
390	        Err(e) => panic!("CARGO_MANIFEST_DIR unset: {e}"),
391	    };
392	    generate_config_schema(&manifest_dir);
393	
394	    let lock_path = Path::new(&manifest_dir).join("Cargo.lock");
395	    println!("cargo::rerun-if-changed={}", lock_path.display());
396	
397	    let lock = match std::fs::read_to_string(&lock_path) {
398	        Ok(text) => text,
399	        Err(e) => panic!("cannot read {}: {e}", lock_path.display()),
400	    };
401	    match jj_lib_version(&lock) {
402	        Some(version) => println!("cargo::rustc-env=JJ_LIB_VERSION={version}"),
403	        None => panic!("no jj-lib package in {}", lock_path.display()),
404	    }
405	}
