/// Every key must point a reader somewhere: a non-empty
/// `reference` url starting with https.
#[test]
fn every_key_has_reference() {
    for key in schema() {
        assert!(
            key.reference.starts_with("https://"),
            "{}: reference {:?} is not an https url",
