1	//! Export the resolved `jj-lib` version as `JJ_LIB_VERSION`,
2	//! guard the single-name convention, and generate the config
3	//! schema from the `vc-config.md` prototype.
4	//!
5	//! jj-lib exports no version constant of its own, so the only
6	//! statement of what this binary links against is the resolved
7	//! version in `Cargo.lock`:
8	//!
9	//! - the lock is read from `$CARGO_MANIFEST_DIR` directly, not by
10	//!   walking ancestors: we are not a workspace, and a walk can
11	//!   bind a sibling project's lock, which is worse than failing.
12	//! - a missing or jj-lib-less lock fails the build rather than
13	//!   emitting an "unknown" that would later be reported as fact.
14	//!
15	//! The name guard (chores-16, 0.78.3): a suffixed version marks a
16	//! dev rung, and a dev rung must never carry the stable package
17	//! name, or installing it replaces the stable `vc-x1` binary with
18	//! unpushed code. It lives here rather than in a `#[test]` because
19	//! `cargo install` never runs tests: a build script runs on every
20	//! cargo verb, so the forbidden combination fails to compile at
21	//! all, install included.
22	
23	use std::path::Path;
24	
25	// The md -> toml filter, shared verbatim with the binary's
26	// instance-config loader: the prototype below and a `.vc-config.md`
27	// are the same format, so they must be read by the same code. A
28	// build script is its own crate and cannot name a crate module, so
29	// the file is pulled in textually.
30	include!("src/md_fence.rs");
31	
32	/// Extract `jj-lib`'s resolved version from `Cargo.lock` text.
33	///
34	/// Scans for the `[[package]]` block whose `name` is `jj-lib` and
35	/// returns that block's `version`. Line-based rather than a TOML
36	/// parse: build scripts get no dev-dependencies, and the lock's
37	/// shape is fixed by cargo.
38	fn jj_lib_version(lock: &str) -> Option<String> {
39	    let mut in_jj_lib = false;
40	    for line in lock.lines() {
41	        let line = line.trim();
42	        if line == "[[package]]" {
43	            in_jj_lib = false;
44	        } else if let Some(rest) = line.strip_prefix("name = ") {
45	            in_jj_lib = rest.trim_matches('"') == "jj-lib";
46	        } else if let Some(rest) = line.strip_prefix("version = ")
47	            && in_jj_lib
48	        {
49	            return Some(rest.trim_matches('"').to_string());
50	        }
51	    }
52	    None
53	}
54	
55	/// The single-name convention's guard: refuse to build a suffixed
56	/// (dev-rung) version under the stable package name.
57	///
58	/// Reported via the `cargo::error` directive rather than `panic!`:
59	/// cargo then prints one clean error line and fails the build,
60	/// instead of wrapping a build-script panic in exit-status and
61	/// backtrace noise.
62	fn guard_single_name() {
63	    let name = env!("CARGO_PKG_NAME");
64	    let version = env!("CARGO_PKG_VERSION");
65	    if version.contains('-') && name == "vc-x1" {
66	        // The version is not echoed in the text: cargo's own
67	        // `error: <name>@<version>:` prefix already carries it.
68	        println!("cargo::error=");
69	        println!("cargo::error=A suffixed version is used with the stable package name, `vc-x1`");
70	        println!("cargo::error=so refusing to build `vc-x1` as it is the stable binary name.");
71	        println!("cargo::error=");
72	    }
73	}
74	
75	/// One key parsed from the `vc-config.toml` prototype, metadata
76	/// as raw strings (typing happens at render time in
77	/// `render_config_schema`).
78	struct ProtoKey {
79	    path: String,
80	    homes: Vec<String>,
81	    kind: String,
82	    doc: String,
83	    used_by: String,
84	    /// Override url; the norm is `None`, deriving
85	    /// `<reference-base>vc-config.md#<anchor_slug(path)>`.
86	    reference: Option<String>,
87	    default: Option<String>,
88	    example: Option<String>,
89	    required: bool,
90	}
91	
92	/// Parse a TOML basic-string body (the text between the quotes),
93	/// unescaping `\"` and `\\`. Anything fancier (unicode escapes,
94	/// multi-line strings) is out of the prototype's dialect and
95	/// fails the build via the caller's validation.
96	fn unescape_basic_string(body: &str) -> String {
97	    let mut out = String::with_capacity(body.len());
98	    let mut chars = body.chars();
99	    while let Some(c) = chars.next() {
100	        if c == '\\' {
101	            match chars.next() {
102	                Some('"') => out.push('"'),
103	                Some('\\') => out.push('\\'),
104	                other => panic!("vc-config.md: unsupported escape \\{other:?}"),
105	            }
106	        } else {
107	            out.push(c);
108	        }
109	    }
110	    out
111	}
112	
113	/// Parse one metadata value: a quoted string, a `[...]` string
114	/// array (returned joined by `\u{0}` for the caller to split), a
115	/// bare integer, or a bare bool. Returns the raw string form.
116	fn parse_value(raw: &str) -> String {
117	    let raw = raw.trim();
118	    if let Some(body) = raw.strip_prefix('"') {
119	        let Some(body) = body.strip_suffix('"') else {
120	            panic!("vc-config.md: unterminated string: {raw}");
121	        };
122	        unescape_basic_string(body)
123	    } else {
124	        raw.to_string()
125	    }
126	}
127	
128	/// Line-based parse of the `vc-config.toml` prototype into
129	/// `ProtoKey`s, file order preserved.
130	///
131	/// Line-based for the same reason `jj_lib_version` is: build
132	/// scripts see no dev-dependencies, and the prototype's dialect
133	/// is ours to bound (single-line `key = value` entries, dotted
134	/// table headers with optionally-quoted segments, `#` comments).
135	fn parse_prototype(text: &str) -> (String, Vec<ProtoKey>) {
136	    let mut keys: Vec<ProtoKey> = Vec::new();
137	    let mut base: Option<String> = None;
138	    let mut current: Option<(String, Vec<(String, String)>)> = None;
139	
140	    fn finish(
141	        keys: &mut Vec<ProtoKey>,
142	        base: &mut Option<String>,
143	        current: Option<(String, Vec<(String, String)>)>,
144	    ) {
145	        let Some((path, fields)) = current else {
146	            return;
147	        };
148	        if path == "vc-config" {
149	            for (name, value) in fields {
150	                match name.as_str() {
151	                    "reference-base" => *base = Some(value),
152	                    other => panic!("vc-config.md: [vc-config]: unknown entry {other:?}"),
153	                }
154	            }
155	            return;
156	        }
157	        let mut homes: Vec<String> = Vec::new();
158	        let mut kind = None;
159	        let mut doc = None;
160	        let mut used_by = None;
161	        let mut reference = None;
162	        let mut default = None;
163	        let mut example = None;
164	        let mut required = false;
165	        for (name, value) in fields {
166	            match name.as_str() {
167	                "homes" => {
168	                    homes = value.split('\u{0}').map(str::to_string).collect();
169	                }
170	                "kind" => kind = Some(value),
171	                "doc" => doc = Some(value),
172	                "used-by" => used_by = Some(value),
173	                "reference" => reference = Some(value),
174	                "default" => default = Some(value),
175	                "example" => example = Some(value),
176	                "required" => match value.as_str() {
177	                    "true" => required = true,
178	                    "false" => required = false,
179	                    other => panic!("vc-config.md: [{path}] required = {other}: not a bool"),
180	                },
181	                other => panic!("vc-config.md: [{path}]: unknown entry {other:?}"),
182	            }
183	        }
